/* Cert Gauntlet — IOS simulator conformance suite.  Run: node dev/tests/ios-conformance.mjs [-v] [filter]
   Each case builds a small topology, types CLI lines exactly as a student would, and checks `show` output
   and ping results. Checks use substrings/regexes rather than full-output equality so cosmetic changes to
   padding don't break the suite, but every line that carries state (addresses, roles, codes, counts) is asserted.
   Scope is the CCNA 200-301 blueprint subset documented in dev/specs/ccna.md. */
import { createLab } from "../../core/sims/ios/index.js";

const verbose = process.argv.includes("-v"); const filter = process.argv.slice(2).find(a => !a.startsWith("-"));
const cases = []; const T = (name, fn) => cases.push({ name, fn });

/* ---------------- shared topologies ---------------- */
const R = type => ({ type: type || "router" });
const PC = (ip, gw, extra = {}) => ({ host: true, ip, mask: "255.255.255.0", gw, ...extra });
function labA(extra = {}) {              // R1 --SW1-- PC1 ; R1 -- R2 -- PC2
  return createLab({
    devices: { R1: R(), R2: R(), SW1: R("switch"), PC1: PC("10.1.1.10", "10.1.1.1"), PC2: PC("10.1.2.10", "10.1.2.1") },
    links: [["R1", "g0/0", "SW1", "g0/1"], ["SW1", "f0/1", "PC1"], ["R1", "g0/1", "R2", "g0/1"], ["R2", "g0/0", "PC2"]],
    configs: {
      R1: ["en", "conf t", "hostname R1", "int g0/0", "ip add 10.1.1.1 255.255.255.0", "no shut", "int g0/1", "ip add 10.1.12.1 255.255.255.0", "no shut", "end"],
      R2: ["en", "conf t", "hostname R2", "int g0/0", "ip add 10.1.2.1 255.255.255.0", "no shut", "int g0/1", "ip add 10.1.12.2 255.255.255.0", "no shut", "int lo0", "ip add 2.2.2.2 255.255.255.255", "end"],
      SW1: ["en", "conf t", "hostname SW1", "end"],
      ...extra.configs,
    },
  });
}
function labSw() {                        // triangle SW1-SW2-SW3, PCs on SW1 (vlan 10) and SW3 (vlan 10), R1 on SW1
  return createLab({
    devices: { SW1: R("switch"), SW2: R("switch"), SW3: R("switch"), PC1: PC("10.1.10.11", "10.1.10.1"), PC3: PC("10.1.10.13", "10.1.10.1"), PC4: PC("10.1.20.14", "10.1.20.1"), R1: R() },
    links: [["SW1", "g0/1", "SW2", "g0/1"], ["SW2", "g0/2", "SW3", "g0/2"], ["SW1", "g0/2", "SW3", "g0/1"], ["SW1", "f0/1", "PC1"], ["SW3", "f0/1", "PC3"], ["SW3", "f0/2", "PC4"], ["SW1", "f0/24", "R1", "g0/0"]],
    configs: {
      SW1: ["en", "conf t", "hostname SW1", "vlan 10", "name USERS", "vlan 20", "name SERVERS", "exit", "int range g0/1-2", "switchport mode trunk", "int f0/1", "switchport mode access", "switchport access vlan 10", "int f0/24", "switchport mode trunk", "end"],
      SW2: ["en", "conf t", "hostname SW2", "vlan 10", "vlan 20", "exit", "int range g0/1-2", "switchport mode trunk", "end"],
      SW3: ["en", "conf t", "hostname SW3", "vlan 10", "vlan 20", "exit", "int range g0/1-2", "switchport mode trunk", "int f0/1", "switchport mode access", "switchport access vlan 10", "int f0/2", "switchport mode access", "switchport access vlan 20", "end"],
      R1: ["en", "conf t", "hostname R1", "int g0/0", "no shut", "int g0/0.10", "encapsulation dot1q 10", "ip add 10.1.10.1 255.255.255.0", "int g0/0.20", "encapsulation dot1q 20", "ip add 10.1.20.1 255.255.255.0", "end"],
    },
  });
}
function labOspf() {                      // R1 - R2 - R3 chain plus R1 - R3 (triangle), loopbacks, PC behind R3
  return createLab({
    devices: { R1: R(), R2: R(), R3: R(), PC3: PC("10.3.3.10", "10.3.3.1") },
    links: [["R1", "g0/0", "R2", "g0/0"], ["R2", "g0/1", "R3", "g0/1"], ["R1", "g0/1", "R3", "g0/0"], ["R3", "g0/2", "PC3"]],
    configs: {
      R1: ["en", "conf t", "hostname R1", "int g0/0", "ip add 10.0.12.1 255.255.255.0", "no shut", "int g0/1", "ip add 10.0.13.1 255.255.255.0", "no shut", "int lo0", "ip add 1.1.1.1 255.255.255.0", "router ospf 1", "router-id 1.1.1.1", "network 10.0.0.0 0.0.255.255 area 0", "network 1.1.1.1 0.0.0.0 area 0", "end"],
      R2: ["en", "conf t", "hostname R2", "int g0/0", "ip add 10.0.12.2 255.255.255.0", "no shut", "int g0/1", "ip add 10.0.23.2 255.255.255.0", "no shut", "int lo0", "ip add 2.2.2.2 255.255.255.0", "router ospf 1", "router-id 2.2.2.2", "network 10.0.0.0 0.0.255.255 area 0", "network 2.2.2.2 0.0.0.0 area 0", "end"],
      R3: ["en", "conf t", "hostname R3", "int g0/0", "ip add 10.0.13.3 255.255.255.0", "no shut", "int g0/1", "ip add 10.0.23.3 255.255.255.0", "no shut", "int g0/2", "ip add 10.3.3.1 255.255.255.0", "no shut", "int lo0", "ip add 3.3.3.3 255.255.255.0", "router ospf 1", "router-id 3.3.3.3", "network 10.0.0.0 0.0.255.255 area 0", "network 3.3.3.3 0.0.0.0 area 0", "network 10.3.3.0 0.0.0.255 area 0", "passive-interface g0/2", "end"],
    },
  });
}
function labNat() {                       // PC1, PC2 - SW1 - R1 (NAT) - ISP (8.8.8.8 loopback)
  return createLab({
    devices: { R1: R(), ISP: R(), SW1: R("switch"), PC1: PC("192.168.1.10", "192.168.1.1"), PC2: PC("192.168.1.11", "192.168.1.1"), SRV: PC("192.168.1.100", "192.168.1.1") },
    links: [["R1", "g0/0", "SW1", "g0/1"], ["SW1", "f0/1", "PC1"], ["SW1", "f0/2", "PC2"], ["SW1", "f0/3", "SRV"], ["R1", "g0/1", "ISP", "g0/0"]],
    configs: {
      R1: ["en", "conf t", "hostname R1", "int g0/0", "ip add 192.168.1.1 255.255.255.0", "ip nat inside", "no shut", "int g0/1", "ip add 203.0.113.2 255.255.255.252", "ip nat outside", "no shut", "exit", "ip route 0.0.0.0 0.0.0.0 203.0.113.1", "end"],
      ISP: ["en", "conf t", "hostname ISP", "int g0/0", "ip add 203.0.113.1 255.255.255.252", "no shut", "int lo0", "ip add 8.8.8.8 255.255.255.255", "end"],
    },
  });
}

/* ---------------- assertions ---------------- */
class Fail extends Error { }
const has = (out, ...subs) => { for (const s of subs) if (!out.includes(s)) throw new Fail(`expected output to contain ${JSON.stringify(s)}\n--- got ---\n${out}`); };
const lacks = (out, ...subs) => { for (const s of subs) if (out.includes(s)) throw new Fail(`expected output NOT to contain ${JSON.stringify(s)}\n--- got ---\n${out}`); };
const match = (out, re) => { if (!re.test(out)) throw new Fail(`expected ${re}\n--- got ---\n${out}`); };
const eq = (a, b, what = "") => { if (a !== b) throw new Fail(`${what} expected ${JSON.stringify(b)} got ${JSON.stringify(a)}`); };
const run = (lab, dev, lines) => { let last = ""; const s = lab.cli(dev); if (s.mode === "user" && !/^en/.test(lines[0])) s.exec("enable"); for (const l of lines) last = s.exec(l).out; return last; };
const sh = (lab, dev, cmd) => { const s = lab.cli(dev); if (s.mode === "user") s.exec("enable"); if (s.mode !== "priv") s.exec("end"); return s.exec(cmd).out; };
const ping = (lab, from, to, pct, opts) => { const r = lab.topo.ping(from, to, { noArpDrop: true, ...opts }); if (r.pct !== pct) throw new Fail(`ping ${from} -> ${to}: expected ${pct}% got ${r.pct}% (${r.marks}) ${r.why || ""}`); return r; };

/* =====================================================================
   1. PARSER, MODES, PROMPTS, HELP
   ===================================================================== */
T("prompts follow the mode: > # (config)# (config-if)# (config-subif)# (config-line)# (config-router)# (config-vlan)# nacl", () => {
  const lab = labA(); const s = lab.cli("SW1"); const r1 = lab.cli("R1");
  eq(s.prompt(), "SW1>"); s.exec("enable"); eq(s.prompt(), "SW1#"); s.exec("configure terminal"); eq(s.prompt(), "SW1(config)#");
  s.exec("interface f0/1"); eq(s.prompt(), "SW1(config-if)#"); s.exec("exit"); s.exec("line vty 0 4"); eq(s.prompt(), "SW1(config-line)#");
  s.exec("vlan 10"); eq(s.prompt(), "SW1(config-vlan)#"); s.exec("end"); eq(s.prompt(), "SW1#");
  r1.exec("en"); r1.exec("conf t"); r1.exec("router ospf 1"); eq(r1.prompt(), "R1(config-router)#"); r1.exec("int g0/1.10"); eq(r1.prompt(), "R1(config-subif)#");
  r1.exec("ip access-list standard MGMT"); eq(r1.prompt(), "R1(config-std-nacl)#"); r1.exec("ip access-list extended WEB"); eq(r1.prompt(), "R1(config-ext-nacl)#");
  r1.exec("int range g0/0 - 1"); eq(r1.prompt(), "R1(config-if-range)#"); r1.exec("exit"); eq(r1.prompt(), "R1(config)#"); r1.exec("exit"); eq(r1.prompt(), "R1#"); r1.exec("disable"); eq(r1.prompt(), "R1>");
});
T("abbreviations: sh ip int br / conf t / int g0/0 / no shut", () => {
  const lab = labA(); const out = sh(lab, "R1", "sh ip int br"); has(out, "GigabitEthernet0/0     10.1.1.1        YES manual up                    up");
});
T("% Ambiguous command for a non-unique prefix", () => { const lab = labA(); const s = lab.cli("R1"); s.exec("en"); eq(s.exec("s").out, '% Ambiguous command:  "s"'); eq(s.exec("conf t").out, "Enter configuration commands, one per line.  End with CNTL/Z."); eq(s.exec("i").out, '% Ambiguous command:  "i"'); });
T("% Incomplete command when arguments are missing", () => { const lab = labA(); const s = lab.cli("R1"); s.exec("en"); s.exec("conf t"); s.exec("int g0/0"); eq(s.exec("ip address 10.1.1.1").out, "% Incomplete command."); s.exec("exit"); eq(s.exec("ip route 10.0.0.0 255.0.0.0").out, "% Incomplete command."); eq(s.exec("hostname").out, "% Incomplete command."); });
T("% Invalid input with the caret under the bad token", () => {
  const lab = labA(); const s = lab.cli("R1"); s.exec("en"); s.exec("conf t"); s.exec("int g0/0");
  const r = s.exec("ip address 10.1.1.1 255.255.255.0 bogus"); eq(r.out, " ".repeat("R1(config-if)#ip address 10.1.1.1 255.255.255.0 ".length) + "^\n% Invalid input detected at '^' marker.");
  const r2 = s.exec("ip addresss 10.1.1.1 255.255.255.0"); eq(r2.out.split("\n")[0].indexOf("^"), "R1(config-if)#ip ".length);
});
T("? lists commands with descriptions and <cr>", () => {
  const lab = labA(); const s = lab.cli("R1"); s.exec("en"); const out = s.exec("show ?").out; has(out, "running-config", "ip ", "version", "interfaces"); lacks(out, "<cr>");
  const out2 = s.exec("show ip route ?").out; has(out2, "<cr>", "ospf", "A.B.C.D");
  s.exec("conf t"); s.exec("int g0/0"); const out3 = s.exec("ip address ?").out; has(out3, "A.B.C.D", "IP address", "dhcp");
});
T("partial ? completes the word list on one line", () => { const lab = labA(); const s = lab.cli("R1"); s.exec("en"); eq(s.exec("sh ip ro?").out, "route"); has(s.exec("sh in?").out, "interfaces", "inventory"); });
T("Tab completion fills a unique prefix and leaves ambiguous ones alone", () => { const lab = labA(); const s = lab.cli("R1"); s.exec("en"); eq(s.complete("conf"), "configure "); eq(s.complete("sh ip int br"), "sh ip int brief "); eq(s.complete("s"), "s"); eq(s.complete("show ip rou"), "show ip route "); });
T("unknown word in EXEC → Translating ... % Unknown command", () => { const lab = labA(); const s = lab.cli("R1"); has(s.exec("shw ip route").out, 'Translating "shw"...domain server (255.255.255.255)', "% Unknown command or computer name, or unable to find computer address"); s.exec("en"); s.exec("conf t"); s.exec("no ip domain-lookup"); s.exec("end"); has(s.exec("pign").out, 'Translating "pign"\n% Unknown'); lacks(s.exec("pign").out, "255.255.255.255"); });
T("do runs EXEC commands from config modes; exit/end leave modes", () => { const lab = labA(); const s = lab.cli("R1"); s.exec("en"); s.exec("conf t"); s.exec("int g0/0"); has(s.exec("do show ip int brief").out, "GigabitEthernet0/0     10.1.1.1"); eq(s.prompt(), "R1(config-if)#"); s.exec("end"); eq(s.prompt(), "R1#"); });
T("no and default forms undo configuration", () => { const lab = labA(); const s = lab.cli("R1"); run(lab, "R1", ["en", "conf t", "int g0/0", "description LAN", "no description", "exit", "ip route 10.9.9.0 255.255.255.0 10.1.12.2", "no ip route 10.9.9.0 255.255.255.0 10.1.12.2", "hostname Foo", "default hostname", "end"]); const o = sh(lab, "R1", "show running-config"); lacks(o, "description LAN", "ip route 10.9.9.0"); eq(s.prompt(), "Router#"); });
T("enable asks for the password when enable secret is set", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "enable secret class", "end", "disable"]); const s = lab.cli("R1"); const r = s.exec("enable"); eq(r.prompt, "Password: "); const r2 = s.exec("wrong"); eq(r2.echo, false); eq(r2.prompt, "Password: "); s.exec("class"); eq(s.prompt(), "R1#"); });
T("banner motd with inline and multi-line delimiter", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "banner motd #Authorized access only#", "end"]); has(sh(lab, "R1", "show run"), "banner motd ^CAuthorized access only^C"); const s = lab.cli("R1"); s.exec("conf t"); const r = s.exec("banner motd %"); has(r.out, "Enter TEXT message.  End with the character '%'."); s.exec("line one"); s.exec("line two%"); eq(s.prompt(), "R1(config)#"); has(sh(lab, "R1", "show run"), "banner motd ^Cline one\nline two^C"); });
T("interface range applies to every member", () => { const lab = labSw(); run(lab, "SW2", ["en", "conf t", "interface range fastEthernet 0/5 - 8", "description RANGE", "shutdown", "end"]); const o = sh(lab, "SW2", "show run"); for (const n of [5, 6, 7, 8]) has(o, `interface FastEthernet0/${n}\n description RANGE\n shutdown`); has(sh(lab, "SW2", "show ip int brief"), "FastEthernet0/6        unassigned      YES unset  administratively down down"); });

/* =====================================================================
   2. GLOBAL CONFIG → RUNNING-CONFIG
   ===================================================================== */
T("hostname changes the prompt and running-config", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "hostname CORE-RTR"]); eq(lab.cli("R1").prompt(), "CORE-RTR(config)#"); has(sh(lab, "R1", "show run"), "hostname CORE-RTR"); eq(lab.cli("R1").exec("conf t").out, "Enter configuration commands, one per line.  End with CNTL/Z."); eq(lab.cli("R1").exec("hostname 1bad").out, "% Hostname contains one or more illegal characters."); });
T("enable secret is stored as type 5; enable password as plain until service password-encryption", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "enable secret class", "enable password cisco", "end"]); const o = sh(lab, "R1", "show run"); match(o, /enable secret 5 \$1\$mERr\$[A-Za-z0-9.\/]{22}/); has(o, "enable password cisco"); run(lab, "R1", ["conf t", "service password-encryption", "end"]); const o2 = sh(lab, "R1", "show run"); has(o2, "service password-encryption", "enable password 7 0822455D0A16"); lacks(o2, "no service password-encryption"); });
T("line con 0: password + login; show run order", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "line con 0", "password cisco", "login", "logging synchronous", "exec-timeout 5 0", "end"]); has(sh(lab, "R1", "show run"), "line con 0\n exec-timeout 5 0\n password cisco\n logging synchronous\n login\nline aux 0"); });
T("line vty 0 4: login local + transport input ssh; username secret", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "username admin secret Cisco123", "username ops privilege 15 secret Ops!", "line vty 0 4", "login local", "transport input ssh", "end"]); const o = sh(lab, "R1", "show run"); match(o, /username admin secret 5 \$1\$mERr\$/); match(o, /username ops privilege 15 secret 5 /); has(o, "line vty 0 4\n login local\n transport input ssh"); });
T("line vty 0 15 configures both vty blocks", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "line vty 0 15", "password cisco", "login", "end"]); has(sh(lab, "R1", "show run"), "line vty 0 4\n password cisco\n login\n transport input telnet ssh\nline vty 5 15\n password cisco\n login"); });
T("login without a password warns", () => { const lab = labA(); const o = run(lab, "R1", ["en", "conf t", "line vty 0 4", "login"]); has(o, "% Login disabled on line 66, until 'password' is set"); });
T("ip domain-name + crypto key generate rsa modulus; refuses without a domain name", () => { const lab = labA(); eq(run(lab, "R1", ["en", "conf t", "crypto key generate rsa modulus 1024"]), "% Please define a domain-name first."); const o = run(lab, "R1", ["ip domain-name lab.local", "crypto key generate rsa modulus 1024"]); has(o, "The name for the keys will be: R1.lab.local", "% The key modulus size is 1024 bits", "[OK]"); run(lab, "R1", ["ip ssh version 2", "end"]); has(sh(lab, "R1", "show ip ssh"), "SSH Enabled - version 2"); has(sh(lab, "R1", "show run"), "ip domain-name lab.local", "ip ssh version 2"); });
T("crypto key generate rsa prompts for the modulus", () => { const lab = labA(); const s = lab.cli("R1"); run(lab, "R1", ["en", "conf t", "ip domain-name lab.local"]); const r = s.exec("crypto key generate rsa"); eq(r.prompt, "How many bits in the modulus [512]: "); has(s.exec("2048").out, "% Generating 2048 bit RSA keys"); eq(s.prompt(), "R1(config)#"); });
T("service password-encryption encrypts line passwords with type 7", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "line vty 0 4", "password cisco", "login", "exit", "service password-encryption", "end"]); has(sh(lab, "R1", "show run"), " password 7 0822455D0A16"); run(lab, "R1", ["conf t", "no service password-encryption", "end"]); has(sh(lab, "R1", "show run"), "no service password-encryption", " password 7 0822455D0A16"); });
T("ntp server shows in running-config and associations", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "ntp server 10.1.12.2", "end"]); has(sh(lab, "R1", "show run"), "ntp server 10.1.12.2"); has(sh(lab, "R1", "show ntp associations"), "*~10.1.12.2"); has(sh(lab, "R1", "show ntp status"), "Clock is synchronized"); });
T("show version is minimal but real-shaped", () => { const lab = labA(); has(sh(lab, "R1", "show version"), "Cisco IOS Software", "R1 uptime is", "Configuration register is 0x2102"); has(sh(lab, "SW1", "show version"), "C2960", "Base ethernet MAC Address"); });

/* =====================================================================
   3. INTERFACES
   ===================================================================== */
T("ip address / no shutdown → show ip interface brief + show interfaces", () => { const lab = labA(); const o = sh(lab, "R1", "show ip interface brief"); has(o, "GigabitEthernet0/1     10.1.12.1       YES manual up                    up", "GigabitEthernet0/2     unassigned      YES unset  administratively down down"); const i = sh(lab, "R1", "show interfaces g0/0"); has(i, "GigabitEthernet0/0 is up, line protocol is up", "Internet address is 10.1.1.1/24", "Hardware is iGbE, address is 0001.4200"); });
T("shutdown drops the line and the peer sees down/down; no shutdown logs the state change", () => { const lab = labA(); const o = run(lab, "R1", ["en", "conf t", "int g0/1", "shutdown"]); has(o, "%LINK-5-CHANGED: Interface GigabitEthernet0/1, changed state to administratively down"); has(sh(lab, "R2", "show ip int brief"), "GigabitEthernet0/1     10.1.12.2       YES manual down                  down"); const o2 = run(lab, "R1", ["conf t", "int g0/1", "no shutdown"]); has(o2, "changed state to up"); has(sh(lab, "R2", "show ip int brief"), "GigabitEthernet0/1     10.1.12.2       YES manual up                    up"); });
T("description, speed and duplex render in running-config and show interfaces", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "int g0/0", "description Link to SW1", "speed 1000", "duplex full", "end"]); has(sh(lab, "R1", "show run"), "interface GigabitEthernet0/0\n description Link to SW1\n ip address 10.1.1.1 255.255.255.0\n duplex full\n speed 1000"); has(sh(lab, "R1", "show interfaces GigabitEthernet0/0"), "Description: Link to SW1", "Full-duplex, 1000Mb/s"); });
T("secondary address and overlap rejection", () => { const lab = labA(); eq(run(lab, "R1", ["en", "conf t", "int g0/2", "ip address 10.1.1.5 255.255.255.0"]), "% 10.1.1.0 overlaps with GigabitEthernet0/0"); run(lab, "R1", ["int g0/0", "ip address 10.1.100.1 255.255.255.0 secondary", "end"]); has(sh(lab, "R1", "show run"), " ip address 10.1.1.1 255.255.255.0\n ip address 10.1.100.1 255.255.255.0 secondary"); });
T("no ip address clears the interface", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "int g0/0", "no ip address", "end"]); has(sh(lab, "R1", "show ip int brief"), "GigabitEthernet0/0     unassigned      YES unset  up                    up"); has(sh(lab, "R1", "show run"), "interface GigabitEthernet0/0\n no ip address"); });
T("loopback interfaces are created on demand and are always up/up", () => { const lab = labA(); run(lab, "R1", ["en", "conf t", "interface Loopback 1", "ip address 1.1.1.1 255.255.255.255", "end"]); has(sh(lab, "R1", "show ip int brief"), "Loopback1              1.1.1.1         YES manual up                    up"); has(sh(lab, "R1", "show ip route"), "C        1.1.1.1/32 is directly connected, Loopback1"); });
T("ipv6 address (global, eui-64, link-local) → show ipv6 interface brief", () => {
  const lab = labA(); run(lab, "R1", ["en", "conf t", "ipv6 unicast-routing", "int g0/0", "ipv6 address 2001:DB8:1:1::1/64", "int g0/1", "ipv6 address 2001:db8:1:12::/64 eui-64", "ipv6 address FE80::1 link-local", "end"]);
  const o = sh(lab, "R1", "show ipv6 interface brief"); has(o, "GigabitEthernet0/0     [up/up]\n    FE80::201:42FF:FE00:", "2001:DB8:1:1::1", "GigabitEthernet0/1     [up/up]\n    FE80::1\n    2001:DB8:1:12:201:42FF:FE00:");
  const r = sh(lab, "R1", "show run"); has(r, "ipv6 unicast-routing", " ipv6 address 2001:DB8:1:1::1/64", " ipv6 address FE80::1 link-local\n ipv6 address 2001:DB8:1:12::/64 eui-64");
});
T("ipv6 static route and ping over IPv6", () => {
  const lab = labA(); run(lab, "R1", ["en", "conf t", "ipv6 unicast-routing", "int g0/1", "ipv6 address 2001:db8:12::1/64", "exit", "ipv6 route 2001:db8:2::/64 2001:db8:12::2", "end"]);
  run(lab, "R2", ["en", "conf t", "ipv6 unicast-routing", "int g0/1", "ipv6 address 2001:db8:12::2/64", "int lo0", "ipv6 address 2001:db8:2::2/64", "end"]);
  const o = sh(lab, "R1", "show ipv6 route"); has(o, "S   2001:DB8:2::/64 [1/0]\n     via 2001:DB8:12::2, GigabitEthernet0/1", "C   2001:DB8:12::/64 [0/0]", "L   2001:DB8:12::1/128 [0/0]");
  has(sh(lab, "R1", "ping 2001:db8:2::2"), "!!!!!", "Success rate is 100 percent"); has(sh(lab, "R1", "ping 2001:db8:3::1"), "Success rate is 0 percent");
});
T("show interfaces status on a switch", () => { const lab = labSw(); const o = sh(lab, "SW1", "show interfaces status"); has(o, "Fa0/1                        connected    10         a-full  a-100  10/100BaseTX", "Gi0/1                        connected    trunk      a-full  a-1000 10/100/1000BaseTX"); match(o, /Fa0\/2\s+notconnect\s+1 /); });

/* =====================================================================
   4. VLANS, TRUNKS, SWITCHING
   ===================================================================== */
T("vlan + name → show vlan brief with port membership", () => { const lab = labSw(); const o = sh(lab, "SW1", "show vlan brief"); has(o, "10   USERS                            active    Fa0/1", "20   SERVERS                          active    ", "1002 fddi-default                     act/unsup"); lacks(o.split("\n").find(l => l.startsWith("1    default")), "Fa0/1"); lacks(o, "Gi0/1"); });
T("switchport access vlan creates a missing vlan with a notice", () => { const lab = labSw(); eq(run(lab, "SW2", ["en", "conf t", "int f0/3", "switchport mode access", "switchport access vlan 30"]), "% Access VLAN does not exist. Creating vlan 30"); has(sh(lab, "SW2", "show vlan brief"), "30   VLAN0030                         active    Fa0/3"); });
T("show interfaces trunk reflects native and allowed vlans", () => { const lab = labSw(); run(lab, "SW1", ["en", "conf t", "int g0/1", "switchport trunk native vlan 99", "switchport trunk allowed vlan 10,20,99", "end"]); const o = sh(lab, "SW1", "show interfaces trunk"); has(o, "Gi0/1       on               802.1q         trunking      99", "Gi0/2       on               802.1q         trunking      1", "Gi0/1       10,20,99", "Gi0/2       1-4094"); has(sh(lab, "SW1", "show run"), " switchport trunk native vlan 99\n switchport trunk allowed vlan 10,20,99\n switchport mode trunk"); });
T("allowed vlan add/remove/except/all", () => { const lab = labSw(); run(lab, "SW1", ["en", "conf t", "int g0/1", "switchport trunk allowed vlan 10", "switchport trunk allowed vlan add 20,30", "switchport trunk allowed vlan remove 30", "end"]); has(sh(lab, "SW1", "show run"), " switchport trunk allowed vlan 10,20\n"); run(lab, "SW1", ["conf t", "int g0/1", "switchport trunk allowed vlan except 1-9", "end"]); has(sh(lab, "SW1", "show run"), " switchport trunk allowed vlan 10-4094"); run(lab, "SW1", ["conf t", "int g0/1", "switchport trunk allowed vlan all", "end"]); lacks(sh(lab, "SW1", "show run"), "allowed vlan"); });
T("show interfaces switchport shows admin/operational mode, access, native, voice vlan", () => { const lab = labSw(); run(lab, "SW1", ["en", "conf t", "int f0/1", "switchport voice vlan 150", "end"]); const o = sh(lab, "SW1", "show interfaces f0/1 switchport"); has(o, "Name: Fa0/1", "Administrative Mode: static access", "Operational Mode: static access", "Access Mode VLAN: 10 (USERS)", "Voice VLAN: 150 (VLAN0150)"); const t = sh(lab, "SW1", "show interfaces g0/1 switchport"); has(t, "Administrative Mode: trunk", "Operational Mode: trunk", "Trunking Native Mode VLAN: 1 (default)"); const d = sh(lab, "SW2", "show interfaces f0/5 switchport"); has(d, "Administrative Mode: dynamic auto", "Operational Mode: down"); });
T("DTP: dynamic auto + dynamic desirable forms a trunk; auto + auto stays access", () => {
  const lab = labSw(); run(lab, "SW1", ["en", "conf t", "int g0/1", "switchport mode dynamic desirable", "end"]); run(lab, "SW2", ["en", "conf t", "int g0/1", "switchport mode dynamic auto", "end"]);
  has(sh(lab, "SW1", "show interfaces g0/1 switchport"), "Administrative Mode: dynamic desirable", "Operational Mode: trunk");
  run(lab, "SW1", ["conf t", "int g0/1", "switchport mode dynamic auto", "end"]); has(sh(lab, "SW1", "show interfaces g0/1 switchport"), "Operational Mode: static access"); has(sh(lab, "SW2", "show interfaces g0/1 switchport"), "Operational Mode: static access");
});
T("switchport nonegotiate conflicts with dynamic modes", () => { const lab = labSw(); eq(run(lab, "SW2", ["en", "conf t", "int f0/5", "switchport nonegotiate"]), "Command rejected: Conflict between 'nonegotiate' and 'dynamic' status."); run(lab, "SW2", ["switchport mode trunk", "switchport nonegotiate", "end"]); has(sh(lab, "SW2", "show run"), " switchport mode trunk\n switchport nonegotiate"); has(sh(lab, "SW2", "show interfaces f0/5 switchport"), "Negotiation of Trunking: Off"); });
T("same-VLAN hosts across trunks can ping; different access VLAN cannot", () => { const lab = labSw(); ping(lab, "PC1", "10.1.10.13", 100); run(lab, "SW3", ["en", "conf t", "int f0/1", "switchport access vlan 20", "end"]); ping(lab, "PC1", "10.1.10.13", 0); });
T("a trunk that does not allow the VLAN blocks it", () => { const lab = labSw(); ping(lab, "PC1", "10.1.10.13", 100); run(lab, "SW2", ["en", "conf t", "int range g0/1-2", "switchport trunk allowed vlan 20", "end"]); run(lab, "SW1", ["en", "conf t", "int g0/2", "shutdown", "end"]); ping(lab, "PC1", "10.1.10.13", 0); run(lab, "SW2", ["conf t", "int range g0/1-2", "switchport trunk allowed vlan add 10", "end"]); ping(lab, "PC1", "10.1.10.13", 100); });
T("native VLAN mismatch leaks untagged frames into the other side's native VLAN", () => { const lab = labSw(); run(lab, "SW1", ["en", "conf t", "int f0/1", "switchport access vlan 1", "int g0/1", "shutdown", "end"]); ping(lab, "PC1", "10.1.10.13", 0); /* PC1 now in vlan 1, PC3 in vlan 10 */ run(lab, "SW3", ["en", "conf t", "int g0/1", "switchport trunk native vlan 10", "end"]); /* PC1 untagged on the SW1-SW3 trunk → SW3 treats it as native vlan 10 → reaches PC3 */ ping(lab, "PC1", "10.1.10.13", 100); has(sh(lab, "SW3", "show interfaces trunk"), "Gi0/1       on               802.1q         trunking      10"); });
T("show mac address-table learns dynamically after traffic", () => { const lab = labSw(); has(sh(lab, "SW1", "show mac address-table"), "Total Mac Addresses for this criterion: 0"); ping(lab, "PC1", "10.1.10.13", 100); const o = sh(lab, "SW1", "show mac address-table"); const pc1 = lab.topo.get("PC1").mac, pc3 = lab.topo.get("PC3").mac; has(o, `  10    ${pc1}    DYNAMIC     Fa0/1`); match(o, new RegExp(`  10    ${pc3.replace(/\\./g, "\\\\.")}    DYNAMIC     Gi0/[12]`)); run(lab, "SW1", ["en", "clear mac address-table dynamic"]); has(sh(lab, "SW1", "show mac address-table"), "criterion: 0"); });
T("router-on-a-stick: subinterfaces with encapsulation dot1q route between VLANs", () => { const lab = labSw(); ping(lab, "PC1", "10.1.20.14", 100); ping(lab, "PC4", "10.1.10.11", 100); has(sh(lab, "R1", "show run"), "interface GigabitEthernet0/0.10\n encapsulation dot1Q 10\n ip address 10.1.10.1 255.255.255.0"); has(sh(lab, "R1", "show ip int brief"), "GigabitEthernet0/0.10  10.1.10.1       YES manual up                    up"); eq(run(lab, "R1", ["en", "conf t", "int g0/0.30", "encapsulation dot1q 10"]), "Command rejected: VLAN 10 is already configured on GigabitEthernet0/0.10"); });
T("router subinterface without encapsulation does not forward the VLAN", () => { const lab = labSw(); run(lab, "R1", ["en", "conf t", "int g0/0.20", "no encapsulation dot1q 20", "end"]); ping(lab, "PC1", "10.1.20.14", 0); });
T("interface vlan (SVI) + ip default-gateway on a Layer-2 switch", () => { const lab = labSw(); run(lab, "SW3", ["en", "conf t", "int vlan 10", "ip address 10.1.10.3 255.255.255.0", "no shut", "exit", "ip default-gateway 10.1.10.1", "end"]); has(sh(lab, "SW3", "show ip int brief"), "Vlan10                 10.1.10.3       YES manual up                    up"); has(sh(lab, "SW3", "show ip route"), "Default gateway is 10.1.10.1"); has(sh(lab, "SW3", "ping 10.1.10.11"), "Success rate is 80 percent (4/5)"); has(sh(lab, "SW3", "ping 10.1.20.14"), "!!!!"); has(sh(lab, "SW3", "show run"), "interface Vlan10\n ip address 10.1.10.3 255.255.255.0", "ip default-gateway 10.1.10.1"); });
T("SVI is up/down when no port (access or trunk) carries its VLAN", () => { const lab = labSw(); run(lab, "SW2", ["en", "conf t", "vlan 77", "exit", "int vlan 77", "ip address 10.77.0.2 255.255.255.0", "end"]); has(sh(lab, "SW2", "show ip int brief"), "Vlan77                 10.77.0.2       YES manual up                    up"); run(lab, "SW2", ["conf t", "int range g0/1-2", "switchport trunk allowed vlan 1,10,20", "end"]); has(sh(lab, "SW2", "show ip int brief"), "Vlan77                 10.77.0.2       YES manual up                    down"); });
T("Layer-3 switch: ip routing + SVIs route between VLANs; no switchport routed port", () => {
  const lab = createLab({ devices: { L3: R("l3switch"), PC1: PC("10.1.10.11", "10.1.10.1"), PC2: PC("10.1.20.12", "10.1.20.1"), R1: R() }, links: [["L3", "g1/0/1", "PC1"], ["L3", "g1/0/2", "PC2"], ["L3", "g1/0/24", "R1", "g0/0"]],
    configs: { L3: ["en", "conf t", "hostname L3", "ip routing", "vlan 10", "vlan 20", "exit", "int g1/0/1", "switchport mode access", "switchport access vlan 10", "int g1/0/2", "switchport mode access", "switchport access vlan 20", "int vlan 10", "ip address 10.1.10.1 255.255.255.0", "int vlan 20", "ip address 10.1.20.1 255.255.255.0", "int g1/0/24", "no switchport", "ip address 10.1.99.1 255.255.255.0", "exit", "ip route 0.0.0.0 0.0.0.0 10.1.99.2", "end"], R1: ["en", "conf t", "int g0/0", "ip add 10.1.99.2 255.255.255.0", "no shut", "exit", "ip route 10.1.0.0 255.255.0.0 10.1.99.1", "end"] } });
  ping(lab, "PC1", "10.1.20.12", 100); ping(lab, "PC1", "10.1.99.2", 100); const o = sh(lab, "L3", "show ip route"); has(o, "C        10.1.10.0/24 is directly connected, Vlan10", "C        10.1.99.0/24 is directly connected, GigabitEthernet1/0/24", "S*    0.0.0.0/0 [1/0] via 10.1.99.2"); has(sh(lab, "L3", "show run"), "ip routing", "interface GigabitEthernet1/0/24\n no switchport\n ip address 10.1.99.1 255.255.255.0");
  run(lab, "L3", ["conf t", "no ip routing", "end"]); ping(lab, "PC1", "10.1.20.12", 0);
});

